def _blob_service(acfg: AdlsConfig, secret: str) -> Any:
    """An ADLS `BlobServiceClient` for `acfg` (caller must `.close()` it)."""
    from azure.storage.blob import BlobServiceClient

    return BlobServiceClient(account_url=acfg.account_url, credential=secret)


class StoreSession:
    """One store client, reused across the reads of a single logical operation (#1329).

    A range-read walk issues many requests where the pre-#882 code issued one
    download, and a client per request is pure overhead on that pattern. The
    session is request-scoped and NOT thread-safe: it is created inside the read
    that uses it and closed with it, so no client is ever module state a Celery
    prefork child could inherit.
    """

    def __init__(self, *, conn_type: str, config: dict[str, Any], secret: str) -> None:
        self.conn_type = conn_type
        self._config = config
        self._secret = secret
        self._client: Any = None
        self._s3_config: S3Config | None = None
        self._adls_config: AdlsConfig | None = None
        #: Clients constructed by this session — asserted by the seam tests.
        self.clients_created = 0
        #: Byte sizes already known per path, for THIS session's lifetime only —
        #: it dedups the count→take pair of one sampled read (#1329), never
        #: seeded from a caller's own, possibly stale, stat (#2004).
        self.sizes: dict[str, int] = {}

    @property
    def s3_config(self) -> S3Config:
        if self._s3_config is None:
            self._s3_config = S3Config.model_validate(self._config)
        return self._s3_config

    @property
    def adls_config(self) -> AdlsConfig:
        if self._adls_config is None:
            self._adls_config = AdlsConfig.model_validate(self._config)
        return self._adls_config

    @property
    def s3(self) -> Any:
        if self._client is None:
            self._client = _s3_client(self.s3_config, self._secret)
            self.clients_created += 1
        return self._client

    @property
    def blob_service(self) -> Any:
        if self._client is None:
            self._client = _blob_service(self.adls_config, self._secret)
            self.clients_created += 1
        return self._client

    def blob(self, path: str) -> Any:
        """A blob client for ``path`` on this session's service client."""
        return self.blob_service.get_blob_client(container=self.adls_config.container, blob=path)

    def close(self) -> None:
        client, self._client = self._client, None
        closer = getattr(client, "close", None)
        if closer is not None:
            closer()

    def __enter__(self) -> StoreSession:
        return self
    *, conn_type: str, config: dict[str, Any], prefix: str, secret: str
) -> Generator[FileRef]:
    """Stream objects/blobs under `prefix` (live seam, generator — #943)."""
    if conn_type == "s3":
        cfg = S3Config.model_validate(config)
        paginator = _s3_client(cfg, secret).get_paginator("list_objects_v2")
        for page in paginator.paginate(Bucket=cfg.bucket, Prefix=prefix):
            for obj in page.get("Contents", []):
                yield FileRef(path=obj["Key"], last_modified=obj.get("LastModified"))
        return

    acfg = AdlsConfig.model_validate(config)
    client_az = _blob_service(acfg, secret)
    try:
        container = client_az.get_container_client(acfg.container)
        for blob in container.list_blobs(name_starts_with=prefix):
            yield FileRef(path=blob.name, last_modified=getattr(blob, "last_modified", None))
    finally:
        client_az.close()


def list_files(
    *, conn_type: str, config: dict[str, Any], prefix: str, secret: str
) -> list[FileRef]:
    """The whole listing under `prefix` as a list (live seam); batch resolution
    uses `iter_files` instead (#943).
    """
    return list(iter_files(conn_type=conn_type, config=config, prefix=prefix, secret=secret))


# ── interactive browse (#466) ───────────────────────────────────────
# One delimited listing page: the immediate "folders" and objects under a prefix, capped at
# `limit` entries. A single bounded request, never a walk — the API threadpool calls it.


@dataclass(frozen=True)
class BrowseFile:
    """An object directly under the browsed prefix."""

    path: str
    size: int | None
    last_modified: datetime | None


@dataclass(frozen=True)
class DirectoryListing:
    """One level of a flat-file store. ``truncated`` means more entries exist under the prefix
    than were returned, so the level is incomplete — never "this is everything".
    """

    folders: list[str]
    files: list[BrowseFile]
    truncated: bool


def _cap(
    folders: list[str], files: list[BrowseFile], *, limit: int, more: bool
) -> DirectoryListing:
    """Merge-order the two lists the way the store listed them and keep the first ``limit``."""
    # A folder marker / HNS directory blob shares its name with a folder prefix; show it once.
    folder_names = {f.rstrip("/") for f in folders}
    files = [f for f in files if f.path.rstrip("/") not in folder_names]
    merged: list[tuple[str, str | BrowseFile]] = [(f, f) for f in folders]
    merged += [(f.path, f) for f in files]
    merged.sort(key=lambda item: item[0])
    kept = merged[:limit]
    return DirectoryListing(
        folders=[entry for _, entry in kept if isinstance(entry, str)],
        files=[entry for _, entry in kept if isinstance(entry, BrowseFile)],
        truncated=more or len(merged) > limit,
    )


def list_directory(
    *, conn_type: str, config: dict[str, Any], prefix: str, secret: str, limit: int
) -> DirectoryListing:
    """The folders and files immediately under ``prefix`` (live seam, one bounded page)."""
    if conn_type == "s3":
        cfg = S3Config.model_validate(config)
        page = _s3_client(cfg, secret).list_objects_v2(
            Bucket=cfg.bucket, Prefix=prefix, Delimiter="/", MaxKeys=limit + 1
        )
        folders = [p["Prefix"] for p in page.get("CommonPrefixes", []) if p.get("Prefix")]
        files = [
            BrowseFile(path=o["Key"], size=o.get("Size"), last_modified=o.get("LastModified"))
            for o in page.get("Contents", [])
            if o.get("Key") and o["Key"] != prefix  # the prefix's own folder marker
        ]
        return _cap(folders, files, limit=limit, more=bool(page.get("IsTruncated")))

    from azure.storage.blob import BlobPrefix

    acfg = AdlsConfig.model_validate(config)
    client_az = _blob_service(acfg, secret)
    try:
        container = client_az.get_container_client(acfg.container)
        walk = container.walk_blobs(
            name_starts_with=prefix or None, delimiter="/", results_per_page=limit + 1
        )
        folders = []
        files = []
        kept = 0
        # Truncation counts KEPT entries: the prefix's own placeholder blob and an HNS
        # directory blob (listed as `a/b` just before its `a/b/` prefix) are dropped, so a raw
        # item count would report a complete level as truncated. The raw bound stays finite —
        # at most one placeholder plus one duplicate per folder.

    return {"capability_probe": _run}


# What the pre-#2112 probe stored for EVERY role that could run DMFs: its own statement tripped
# the bare-column rule and was classified as a FRESHNESS column-type problem.
_MISPROBED_DMF_REASON_PREFIX = "Snowflake's FRESHNESS data metric function accepts"


def clear_misprobed_dmf_capabilities(session: Session, *, apply: bool) -> list[uuid.UUID]:
    """Drop the `dmf` capability the pre-#2112 probe wrongly stored, so the connection reads
    "not yet tested" until its next test re-probes it. Returns the affected connection ids;
    writes only when ``apply``.
    """
    affected: list[uuid.UUID] = []
    for conn in session.scalars(
        select(Connection).where(Connection.type == "snowflake").with_for_update()
    ):
        capabilities = conn.engine_capabilities or {}
        dmf = capabilities.get("dmf")
        if (
            isinstance(dmf, dict)
            and dmf.get("available") is False
            and str(dmf.get("reason", "")).startswith(_MISPROBED_DMF_REASON_PREFIX)
        ):
            affected.append(conn.id)
            remaining = {k: v for k, v in capabilities.items() if k != "dmf"}
            conn.engine_capabilities = remaining or None
    if apply:
        session.commit()
    else:
        session.rollback()
    return affected


def _persist_engine_capabilities(
    session: Session, conn: Connection, capabilities: dict[str, Any]
) -> None:
    """Soft signal, never a test failure: a connection can test successfully even
    when a native engine isn't available on it, so a persistence error here is
    logged and swallowed, not raised (#1867).
    """
    if not capabilities:
        return
    try:
        conn.engine_capabilities = capabilities
        session.commit()
    except Exception:
        # A commit failure here must not turn a genuinely successful connectivity
        # test into a 500.
        session.rollback()
        log.warning("connection_capability_probe_persist_failed", connection_id=str(conn.id))
        return
    log.info(
        "connection_capability_probe_completed",
        connection_id=str(conn.id),
        dmf_available=capabilities.get("dmf", {}).get("available"),
    )


def test_connection(
    session: Session,
    connection_id: uuid.UUID,
    *,
    secret_store: SecretStore,
) -> None:
    """Resolve the connection's secret and probe live connectivity."""
    conn = get_connection(session, connection_id)
    adapter = get_connection_adapter(conn.type)
    secret_optional = getattr(adapter, "secret_optional", False)

    secret: str | None = None
    if conn.secret_ref:
        try:
            secret = secret_store.get(conn.secret_ref)
        except SecretNotFoundError as exc:
            raise ConnectionTestFailedError(
                "credential could not be resolved", detail={"connection_id": str(connection_id)}
            ) from exc
    elif not secret_optional:
