    last: "_RecordingClient | None" = None
    walk_error: Exception | None = None

    def __init__(self, **kwargs: Any) -> None:
        self.kwargs = kwargs
        self.calls: list[str] = []
        self.closed = False
        _RecordingClient.last = self

